'use strict';

// Packages the existing public WESTO front end for Sites without changing the
// local Express runtime. Operational APIs remain local-only; the worker serves
// a read-only public menu snapshot generated by the existing payload factory.
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const DIST = path.join(ROOT, 'dist');
// Sites binds public assets from the build root. Keep the worker isolated in
// dist/server while every page, stylesheet, image, and generated snapshot is
// staged directly beneath dist so env.ASSETS can resolve its original URLs.
const STATIC = DIST;
const WORKER_SOURCE = path.join(ROOT, 'sites', 'public-worker.js');

function reset(directory) {
  fs.rmSync(directory, { recursive: true, force: true });
  fs.mkdirSync(directory, { recursive: true });
}

function copy(relative) {
  const from = path.join(ROOT, relative);
  const to = path.join(STATIC, relative);
  if (!fs.existsSync(from)) throw new Error(`Missing public asset: ${relative}`);
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.cpSync(from, to, { recursive: true });
}

execFileSync(process.execPath, [path.join(ROOT, 'scripts', 'build-static-content-bootstrap.js')], {
  cwd: ROOT,
  stdio: 'inherit',
});

reset(DIST);
for (const directory of ['assets', 'css', 'js', 'uploads']) copy(directory);
for (const file of fs.readdirSync(ROOT)) {
  if (file.endsWith('.html')) copy(file);
}
for (const file of ['manifest.webmanifest', 'sw.js']) copy(file);

const workerOutput = path.join(DIST, 'server', 'index.js');
fs.mkdirSync(path.dirname(workerOutput), { recursive: true });
fs.copyFileSync(WORKER_SOURCE, workerOutput);

console.log(`Sites static package staged in ${path.relative(ROOT, DIST)}`);
